-- Name: fn_fleet_emergency_reassignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_fleet_emergency_reassignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orders_freed INT;
BEGIN
    -- Only act when a truck goes from Active to Inactive
    IF OLD.Active = 1 AND NEW.Active = 0 THEN

        -- Unassign driver from all pending (undelivered) orders
        UPDATE "ORDER"
        SET DriverID = NULL
        WHERE DriverID = OLD.DriverID
          AND DeliveryDate IS NULL;

        -- Count how many orders were freed
        GET DIAGNOSTICS v_orders_freed = ROW_COUNT;

        RAISE NOTICE 'ALERT: Truck (DriverID=%) went offline. % pending orders have been freed for reassignment.',
                     OLD.DriverID, v_orders_freed;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Fleet emergency trigger failed for DriverID %: %', OLD.DriverID, SQLERRM;
END;
$$;


--
-- TOC entry 253 (class 1255 OID 33485)
-- Name: fn_realtime_inventory_deduction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_realtime_inventory_deduction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_store_id     INT;
    v_current_qty  INT;
    v_min_stock    INT;
BEGIN
    -- Get the store linked to this order
    SELECT StoreID INTO v_store_id
    FROM "ORDER"
    WHERE OrderId = NEW.OrderId;

    -- Only process if order belongs to a store (not a customer-only order)
    IF v_store_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Get current inventory for this product in this store
    SELECT Quantity, MinimumStock INTO v_current_qty, v_min_stock
    FROM INVENTORY
    WHERE ProductID = NEW.ProductID
      AND StoreID = v_store_id;

    -- Guard: if product not in inventory for this store, skip silently
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Guard: prevent deduction below zero
    IF v_current_qty < NEW.Quantity THEN
        RAISE EXCEPTION 'Insufficient stock: product % has only % units in store %, but % were ordered.',
                        NEW.ProductID, v_current_qty, v_store_id, NEW.Quantity;
    END IF;

    -- Deduct purchased quantity from store inventory
    UPDATE INVENTORY
    SET Quantity = Quantity - NEW.Quantity
    WHERE ProductID = NEW.ProductID
      AND StoreID = v_store_id;

    -- Alert if stock drops below minimum after deduction
    IF (v_current_qty - NEW.Quantity) < v_min_stock THEN
        RAISE NOTICE 'LOW STOCK WARNING: Product % in store % is now below minimum stock (remaining: %, min: %).',
                     NEW.ProductID, v_store_id,
                     (v_current_qty - NEW.Quantity), v_min_stock;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$$;


--
-- TOC entry 250 (class 1255 OID 33435)
-- Name: generate_predictive_restock_plan(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_predictive_restock_plan(p_store_id integer) RETURNS refcursor
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- [b] Returning a Ref Cursor
    v_report_cursor refcursor;
    
    -- Variables 
    v_store_check INT;
    v_total_sold INT;
    v_daily_velocity NUMERIC(10,2);
    v_days_left INT;
    v_alert_level VARCHAR(20);
    v_days_history INT := 30; 
    
    -- [g] Record declaration
    v_prod_record RECORD;
    
    -- [a] Explicit Cursor
    cur_inventory CURSOR FOR 
        SELECT i.ProductID, p.ProductName, i.Quantity, i.MinimumStock
        FROM INVENTORY i
        JOIN PRODUCT p ON i.ProductID = p.ProductID
        WHERE i.StoreID = p_store_id;

BEGIN
    -- [f] Business Exception Handling
    SELECT StoreID INTO v_store_check FROM STORE WHERE StoreID = p_store_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Error: Store ID % does not exist in the database.', p_store_id;
    END IF;

    -- [c] DML: Creation and manipulation of a temporary table
    DROP TABLE IF EXISTS temp_stock_prediction;
    CREATE TEMP TABLE temp_stock_prediction (
        ProductID INT,
        ProductName VARCHAR,
        CurrentStock INT,
        MinimumStock INT,
        DailyVelocity NUMERIC(10,2),
        DaysUntilEmpty INT,
        AlertLevel VARCHAR
    );

    OPEN cur_inventory;
    -- [e] Main Loop
    LOOP
        FETCH cur_inventory INTO v_prod_record;
        EXIT WHEN NOT FOUND;

        -- [a] Implicit Cursor via SELECT INTO
        SELECT COALESCE(SUM(c.Quantity), 0) INTO v_total_sold
        FROM "ORDER" o
        JOIN CONTAINS c ON o.OrderId = c.OrderId
        WHERE o.StoreID = p_store_id 
          AND c.ProductID = v_prod_record.ProductID
          AND o.OrderDate >= CURRENT_DATE - v_days_history;

        -- [d] Branching (IF / ELSE)
        IF v_total_sold > 0 THEN
            v_daily_velocity := v_total_sold::NUMERIC / v_days_history;
            v_days_left := ROUND(v_prod_record.Quantity / NULLIF(v_daily_velocity, 0));
        ELSE
            v_daily_velocity := 0;
            v_days_left := 9999; 
        END IF;

        IF v_days_left <= 3 THEN
            v_alert_level := 'CRITICAL';
        ELSIF v_days_left <= 7 THEN
            v_alert_level := 'WARNING';
        ELSIF v_prod_record.Quantity < v_prod_record.MinimumStock THEN
            v_alert_level := 'BELOW MIN STOCK'; 
        ELSE
            v_alert_level := 'SAFE';
        END IF;

        -- [c] DML: Insertion
        VALUES (v_prod_record.ProductID, v_prod_record.ProductName, v_prod_record.Quantity, 
                v_prod_record.MinimumStock, v_daily_velocity, v_days_left, v_alert_level);
    END LOOP;
    CLOSE cur_inventory;

    OPEN v_report_cursor FOR 
        SELECT * FROM temp_stock_prediction ORDER BY DaysUntilEmpty ASC;
        
    RETURN v_report_cursor;

EXCEPTION
    -- [f] Global Exceptions
    WHEN OTHERS THEN
        RAISE NOTICE 'System error: %', SQLERRM;
        RAISE;
END;
$$;


--
-- TOC entry 254 (class 1255 OID 33482)
-- Name: monthly_customer_loyalty_batch(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.monthly_customer_loyalty_batch()
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- [a] Explicit cursor to iterate over all customers in the database
    cur_customers CURSOR FOR SELECT CustomerID FROM CUSTOMER;
    v_customer_id INT;
    v_total_spent NUMERIC;
    v_new_tier VARCHAR(20);
BEGIN
    -- [e] Loop through the cursor to process each customer one by one
    OPEN cur_customers;
    LOOP
        FETCH cur_customers INTO v_customer_id;
        EXIT WHEN NOT FOUND;

        -- [a] Implicit cursor to calculate the total amount spent by the current customer
        SELECT COALESCE(SUM(Price), 0) INTO v_total_spent
        FROM "ORDER" 
        WHERE CustomerID = v_customer_id;

        -- [d] Branching IF/ELSIF/ELSE to determine the loyalty tier based on spending
        IF v_total_spent >= 5000 THEN
            v_new_tier := 'VIP Gold';
        ELSIF v_total_spent >= 1000 THEN
            v_new_tier := 'Premium';
        ELSE
            v_new_tier := 'Standard';
        END IF;

        -- [c] DML 1: Mass UPDATE to apply the calculated tier to the customer
        UPDATE CUSTOMER 
        SET LoyaltyTier = v_new_tier 
        WHERE CustomerID = v_customer_id;
        
    END LOOP;
    CLOSE cur_customers;

    -- [c] DML 2: Mass DELETE (Database Cleanup)
    -- Remove old cancelled orders (older than 1 year) to free up database storage
    DELETE FROM "ORDER" 
    WHERE Status = 'Cancelled' AND OrderDate < CURRENT_DATE - INTERVAL '1 year';

    -- Success Message displayed in the console
    RAISE NOTICE 'SUCCESS: End-of-month batch completed. Loyalty tiers updated and old cancelled orders removed.';

EXCEPTION
    -- [f] Global exception handling: Catch any unexpected error and rollback all changes safely
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Batch process failed due to an unexpected error: %', SQLERRM;
        ROLLBACK;
END;
$$;


