-- TOC entry 251 (class 1255 OID 33476)
-- Name: optimize_fleet_loading(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.optimize_fleet_loading(p_delivery_cie_id integer) RETURNS refcursor
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- [b] Ref Cursor
    v_manifest_cursor refcursor;
    
    v_cie_check INT;
    v_current_truck_load INT;
    v_total_assigned INT := 0;
    
    -- [g] Records
    v_truck_record RECORD;
    v_order_record RECORD;
    
    -- [a] Explicit Cursor
    cur_active_trucks CURSOR FOR 
        SELECT DriverID, Capacity 
        FROM TRUCK 
        WHERE DeliveryCieID = p_delivery_cie_id AND Active = 1 
        ORDER BY Capacity DESC;

BEGIN
    -- [f] Custom exception
    SELECT DeliveryCieID INTO v_cie_check FROM DELIVERYCOMPAGNY WHERE DeliveryCieID = p_delivery_cie_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Operation cancelled: Delivery company % does not exist.', p_delivery_cie_id;
    END IF;

    -- [c] DML commands
    DROP TABLE IF EXISTS temp_loading_manifest;
    CREATE TEMP TABLE temp_loading_manifest (
        DriverID INT,
        AssignedOrderID INT,
        TruckCapacity INT,
        AssignmentTime TIMESTAMP
    );

    OPEN cur_active_trucks;
    -- [e] Loop 1 (Trucks)
    LOOP
        FETCH cur_active_trucks INTO v_truck_record;
        EXIT WHEN NOT FOUND;

        v_current_truck_load := 0; 

        -- [a] Implicit Cursor + [e] Loop 2 (Orders)
        FOR v_order_record IN 
            SELECT OrderId FROM "ORDER" WHERE DriverID IS NULL ORDER BY OrderDate ASC
        LOOP
            -- [d] IF Branching
            IF v_current_truck_load < v_truck_record.Capacity THEN
                
                -- [c] DML: UPDATE the actual database
                UPDATE "ORDER" 
                SET DriverID = v_truck_record.DriverID 
                WHERE OrderId = v_order_record.OrderId;
                
                -- [c] DML: INSERT into the report
                VALUES (v_truck_record.DriverID, v_order_record.OrderId, v_truck_record.Capacity, CURRENT_TIMESTAMP);
                
                v_current_truck_load := v_current_truck_load + 1;
                v_total_assigned := v_total_assigned + 1;
            ELSE
                EXIT; -- Exit the orders loop, move to the next truck
            END IF;
        END LOOP;
        
    END LOOP;
    CLOSE cur_active_trucks;

    IF v_total_assigned = 0 THEN
        RAISE NOTICE 'No orders assigned.';
    END IF;

    OPEN v_manifest_cursor FOR 
        SELECT * FROM temp_loading_manifest ORDER BY DriverID, AssignedOrderID;
        
    RETURN v_manifest_cursor;

EXCEPTION
    -- [f] System error handling
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Duplication error during assignment.';
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Algorithm error: %', SQLERRM;
END;
$$;


--
-- TOC entry 252 (class 1255 OID 33480)
-- Name: process_store_inventory_transfer(integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.process_store_inventory_transfer(IN p_product_id integer, IN p_target_store_id integer, IN p_transfer_qty integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- [g] Record to hold the source store information
    v_source_store RECORD;
    v_product_exists INT;
BEGIN
    -- [f] Business Exception: Check if the product exists
    SELECT ProductID INTO v_product_exists FROM PRODUCT WHERE ProductID = p_product_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer cancelled: Product % does not exist.', p_product_id;
    END IF;

    -- [a] Implicit cursor: Find the best store to take the inventory from
    -- We look for a store (different from target) that has enough stock (Current > Minimum + Quantity)
    SELECT StoreID, Quantity INTO v_source_store
    FROM INVENTORY
    WHERE ProductID = p_product_id 
      AND StoreID != p_target_store_id
      AND Quantity >= (MinimumStock + p_transfer_qty)
    ORDER BY Quantity DESC -- Take from the store with the largest excess
    LIMIT 1;

    -- [d] IF / ELSE Branching
    IF v_source_store.StoreID IS NULL THEN
        -- If no store has enough excess stock, raise an error
        RAISE EXCEPTION 'Failed: No store has enough excess stock for product %.', p_product_id;
    ELSE
        -- [c] DML 1: Deduct from the source store
        UPDATE INVENTORY 
        SET Quantity = Quantity - p_transfer_qty 
        WHERE ProductID = p_product_id AND StoreID = v_source_store.StoreID;

        -- [c] DML 2: Add to the target store
        UPDATE INVENTORY 
        SET Quantity = Quantity + p_transfer_qty 
        WHERE ProductID = p_product_id AND StoreID = p_target_store_id;

        -- Success message
        RAISE NOTICE 'SUCCESS: % units of product % transferred from Store % to Store %.', 
                     p_transfer_qty, p_product_id, v_source_store.StoreID, p_target_store_id;
    END IF;
    
EXCEPTION
    -- [f] Global error handling with ROLLBACK for data safety
    WHEN OTHERS THEN
        RAISE NOTICE 'An unexpected error occurred: %', SQLERRM;
        ROLLBACK; 
END;
$$;


